import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.D6RJXrbK.js";const p="/openfga-book/assets/lab6-bug.u5a-iQ56.png",i="/openfga-book/assets/lab6-fixed.B39RydvZ.png",m=JSON.parse('{"title":"Lab 6：mini-openfga v0.6：在浏览器里找出模型的错误","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/lab-6-playground.md","filePath":"chapters/lab-6-playground.md","lastUpdated":1791513046000}'),o={name:"chapters/lab-6-playground.md"};function r(d,a,l,c,h,g){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="lab-6-mini-openfga-v0-6-在浏览器里找出模型的错误" tabindex="-1">Lab 6：mini-openfga v0.6：在浏览器里找出模型的错误 <a class="header-anchor" href="#lab-6-mini-openfga-v0-6-在浏览器里找出模型的错误" aria-label="Permalink to &quot;Lab 6：mini-openfga v0.6：在浏览器里找出模型的错误&quot;">​</a></h1><blockquote><p>目标：用 Playground 完成一次完整的调试：建 store、写一个<strong>有错误</strong>的模型和几条元组，通过 Check 发现异常，用解析树定位原因，修改模型、保存为新版本，再确认修复。 前置：第 25、26 章。对应代码：mini-openfga <strong>v0.6</strong>（本 Lab 的文件在 v1.0 的 <code>examples/lab6/</code>）。</p></blockquote><h2 id="_1-启动" tabindex="-1">1. 启动 <a class="header-anchor" href="#_1-启动" aria-label="Permalink to &quot;1. 启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/mini-openfga</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.6</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minifga</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/minifga</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./minifga</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8080</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 浏览器打开 http://127.0.0.1:8080/playground/</span></span></code></pre></div><p>点 “+ New store”，起名 <code>team-wiki</code>。新 store 会带一个示例模型。</p><h2 id="_2-一个团队-wiki-的模型-有一个错误" tabindex="-1">2. 一个团队 wiki 的模型（有一个错误） <a class="header-anchor" href="#_2-一个团队-wiki-的模型-有一个错误" aria-label="Permalink to &quot;2. 一个团队 wiki 的模型（有一个错误）&quot;">​</a></h2><p>把编辑器的内容换成 <code>examples/lab6/model-buggy.fga</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>model</span></span>
<span class="line"><span>  schema 1.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type user</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type team</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define member: [user]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type space</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define admin: [user]</span></span>
<span class="line"><span>    define editor: [user, team#member] or admin</span></span>
<span class="line"><span>    define viewer: [user, team#member]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type page</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define space: [space]</span></span>
<span class="line"><span>    define author: [user]</span></span>
<span class="line"><span>    define editor: [user] or author or editor from space</span></span>
<span class="line"><span>    define viewer: [user] or viewer from space</span></span></code></pre></div><p>意图是：页面属于一个空间；空间管理员是空间的编辑者；页面的作者和空间的编辑者能编辑页面；<strong>能编辑的人当然也能看</strong>。状态栏显示 OK，点 “Save new version”。</p><p>在元组面板里写入 <code>examples/lab6/tuples.txt</code> 的 5 条：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>team:product#member@user:pat</span></span>
<span class="line"><span>space:product#viewer@team:product#member</span></span>
<span class="line"><span>space:product#admin@user:sara</span></span>
<span class="line"><span>page:roadmap#space@space:product</span></span>
<span class="line"><span>page:roadmap#author@user:alex</span></span></code></pre></div><h2 id="_3-发现异常" tabindex="-1">3. 发现异常 <a class="header-anchor" href="#_3-发现异常" aria-label="Permalink to &quot;3. 发现异常&quot;">​</a></h2><p>在 check 标签页里依次查询：</p><table tabindex="0"><thead><tr><th>查询</th><th>结果</th></tr></thead><tbody><tr><td><code>page:roadmap#viewer@user:pat</code></td><td>ALLOWED</td></tr><tr><td><code>page:roadmap#editor@user:sara</code></td><td>ALLOWED</td></tr><tr><td><code>page:roadmap#viewer@user:sara</code></td><td><strong>DENIED</strong></td></tr><tr><td><code>page:roadmap#viewer@user:alex</code></td><td><strong>DENIED</strong></td></tr></tbody></table><p>sara 是空间管理员，能编辑 roadmap，却<strong>不能看</strong>；作者 alex 也一样。“能改不能看”几乎总是模型写错了。</p><h2 id="_4-用解析树定位" tabindex="-1">4. 用解析树定位 <a class="header-anchor" href="#_4-用解析树定位" aria-label="Permalink to &quot;4. 用解析树定位&quot;">​</a></h2><p>查询 <code>page:roadmap#viewer@user:sara</code>，看下面的树：</p><p><img src="`+p+`" alt="Lab 6：sara 不能看 roadmap 的解析树"></p><p><em>图 L6-1：有错误的模型下，<code>page:roadmap#viewer@user:sara</code> 为 DENIED。</em></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▾ relation  page:roadmap#viewer@user:sara  false</span></span>
<span class="line"><span>  ▾ union   or  false</span></span>
<span class="line"><span>    · direct  [user]  false</span></span>
<span class="line"><span>    ▾ ttu     viewer from space  false</span></span>
<span class="line"><span>      ▾ tuple   page:roadmap#space@space:product  false</span></span>
<span class="line"><span>        ▾ relation  space:product#viewer@user:sara  false</span></span>
<span class="line"><span>          ▸ direct  [user, team#member]  false</span></span></code></pre></div><p>读法：<code>viewer</code> 的 union 只有<strong>两个</strong>分支，直接赋值和 <code>viewer from space</code>。沿着空间往上找，<code>space:product#viewer</code> 只认直接的用户和团队成员，sara 都不是。树里<strong>根本没有一个分支经过 editor</strong>，这就是答案：模型里 <code>viewer</code> 没有包含 <code>editor</code>。</p><p>这也是解析树和“只看结果”的区别：DENIED 本身不能告诉你是数据缺了一条，还是模型少了一条路径；树把所有尝试过的路径都列了出来，缺的那条路径一眼就能看出来。</p><h2 id="_5-修复并确认" tabindex="-1">5. 修复并确认 <a class="header-anchor" href="#_5-修复并确认" aria-label="Permalink to &quot;5. 修复并确认&quot;">​</a></h2><p>把最后一行改成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    define viewer: [user] or editor or viewer from space</span></span></code></pre></div><p>保存为新版本，再查一遍：</p><table tabindex="0"><thead><tr><th>查询</th><th>修复前</th><th>修复后</th></tr></thead><tbody><tr><td><code>page:roadmap#viewer@user:pat</code></td><td>ALLOWED</td><td>ALLOWED</td></tr><tr><td><code>page:roadmap#editor@user:sara</code></td><td>ALLOWED</td><td>ALLOWED</td></tr><tr><td><code>page:roadmap#viewer@user:sara</code></td><td>DENIED</td><td><strong>ALLOWED</strong></td></tr><tr><td><code>page:roadmap#viewer@user:alex</code></td><td>DENIED</td><td><strong>ALLOWED</strong></td></tr></tbody></table><p><img src="`+i+`" alt="Lab 6：修复后"></p><p><em>图 L6-2：修复后的模型，sara 通过 editor ← editor from space ← space admin 获得 viewer。注意 <code>editor from space true</code> 这一行是折叠的（▸），这是下面第 6 节说的第二个界面问题，点开它能看到 <code>space:product#editor</code> ← <code>admin</code> ← <code>space:product#admin@user:sara</code>。</em></p><p>切到 list-users 标签页，查 <code>page:roadmap</code> 的 <code>viewer</code>、过滤 <code>user</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user:alex, user:pat, user:sara</span></span></code></pre></div><p>不需要改任何元组，旧的元组在新模型下自动有了新的含义（第 22 章：元组不属于任何模型版本）。</p><p>以上结果都是用 Playwright 脚本驱动无头 Chrome 在 v0.6 上实际跑出来的，整个过程没有任何 HTTP 错误。</p><h2 id="_6-本-lab-发现的界面问题" tabindex="-1">6. 本 Lab 发现的界面问题 <a class="header-anchor" href="#_6-本-lab-发现的界面问题" aria-label="Permalink to &quot;6. 本 Lab 发现的界面问题&quot;">​</a></h2><p>这两张截图里有两个问题，都在 v1.0 修复了。</p><p><strong>版本下拉框过时</strong>。模型版本下拉框显示的是 <code>KR8D83GN</code>，也就是新建 store 时的示例模型，而编辑器里是刚保存的新模型。原因是 <code>&lt;select&gt;</code> 没有绑定 <code>value</code>（非受控组件）：保存后列表刷新了，浏览器仍然选着原来那个选项，而它已经不是第一项，也就没有 “latest” 标记。v1.0 改成了受控组件。同一个脚本对比：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v1.0:  model: saved as 01M4F4VNHCHBVEVPYWANNZ7CXX | dropdown: latest · ANNZ7CXX</span></span>
<span class="line"><span>v0.6:  model: saved as 01M4F4VRY740ZDE0MEZ9BW6G5V | dropdown: WAEM8X3X</span></span></code></pre></div><p><strong>解析树的展开状态串了</strong>。图 L6-2 里，决定结果的 <code>editor from space true</code> 是折叠的，而默认规则是“为 true 的节点展开”。原因是上一次查询（alex）的树形状相同，那个位置的节点是 false、折叠的，React 复用了组件，折叠状态被继承了下来（第 26 章 26.6 节）。复现脚本先查 alex 再查 sara：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v0.6:  page:roadmap#viewer@user:sara    &quot;editor from space&quot;: ▸ true</span></span>
<span class="line"><span>v1.0:  page:roadmap#viewer@user:sara    &quot;editor from space&quot;: ▾ true</span></span></code></pre></div><p>这个问题对调试工具是致命的：它恰好藏起了你要找的那条路径。</p><h2 id="_7-动手改" tabindex="-1">7. 动手改 <a class="header-anchor" href="#_7-动手改" aria-label="Permalink to &quot;7. 动手改&quot;">​</a></h2><ol><li><strong>用断言固定行为</strong>：用第 23 章的 <code>PUT /stores/{id}/assertions/{model_id}</code> 给修复后的模型写 4 条断言（上面表格的“修复后”一列），再用 <code>POST .../assertions/{model_id}/run</code> 执行。然后对<strong>修复前</strong>的模型 ID 写同样的断言并执行，看哪些失败。</li><li><strong>另一个常见错误</strong>：把 <code>space</code> 的 <code>editor</code> 改成 <code>define editor: [user, team#member]</code>（去掉 <code>or admin</code>），哪些查询会变？先预测，再用解析树验证。</li><li><strong>上下文元组</strong>：不写入元组，在 check 的 “contextual tuples” 里填 <code>space:product#admin@user:zoe</code>，查 <code>page:roadmap#viewer@user:zoe</code>。这种用法适合什么场景？（第 13 章）</li></ol><h2 id="_8-本版小结" tabindex="-1">8. 本版小结 <a class="header-anchor" href="#_8-本版小结" aria-label="Permalink to &quot;8. 本版小结&quot;">​</a></h2><p>v0.6 给 mini-openfga 加上了浏览器界面：模型编辑器（边输入边校验、版本列表）、元组面板、五种查询，以及 Check 的解析树。它和 HTTP API 打包在同一个二进制里。</p><p>Part VIII 进入平台化：带权图与策略选择、规划器、认证、可观测性、部署，以及怎样系统地验证正确性。</p>`,45)])])}const b=e(o,[["render",r]]);export{m as __pageData,b as default};
